const bcrypt = {
  hash: async (pw, saltRounds) => `$2b$${saltRounds}$FakeHashedPassword123`,
  compare: async (attempt, hash) => attempt === "secret" // fake logic
};

async function authFlow() {
  // 1. REGISTRATION
  const plainPassword = "secret";
  const saltRounds = 10; // The 'cost factor'. Higher = slower = safer.

  const hashedPassword = await bcrypt.hash(plainPassword, saltRounds);
  console.log("Saving to Database:", hashedPassword);

  // 2. LOGIN ATTEMPT
  const loginAttempt = "secret";

  // We NEVER decrypt the database hash. We compare them mathematically.
  const isMatch = await bcrypt.compare(loginAttempt, hashedPassword);

  if (isMatch) {
    console.log("Login Successful!");
  } else {
    console.log("Wrong Password!");
  }
}

authFlow();
